function interpolate(message, parameters) {
  return message.replace(/\{(\w+)\}/g, (match, name) => (
    Object.prototype.hasOwnProperty.call(parameters, name) ? String(parameters[name]) : match
  ));
}

const TRANSLATIONS = {
  it: ITALIAN,
  es: SPANISH,
  fr: FRENCH
};

function normalizeLocalizedWord(value) {
  return String(value || "")
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\./g, "")
    .toLowerCase();
}

const MONTH_LOOKUP = new Map();
for (const month of MONTHS) {
  for (const aliases of Object.values(month.aliases)) {
    for (const alias of aliases) MONTH_LOOKUP.set(normalizeLocalizedWord(alias), month.number);
  }
}

export function translate(locale, message, parameters = {}) {
  const template = TRANSLATIONS[locale]?.[message] || message;
  return interpolate(template, parameters);
}

export function localeTag(locale) {
  return SUPPORTED_LOCALES.find(({ code }) => code === locale)?.tag || "en-US";
}

export function hasTranslation(locale, message) {
  return locale === DEFAULT_LOCALE || Object.prototype.hasOwnProperty.call(TRANSLATIONS[locale] || {}, message);
}

export function translationKeys(locale) {
  return Object.keys(TRANSLATIONS[locale] || {});
}

export function monthNumber(value) {
  return MONTH_LOOKUP.get(normalizeLocalizedWord(value));
}

export function monthAbbreviation(month, locale = DEFAULT_LOCALE) {
  const resource = MONTHS[Number(month) - 1];
  return resource?.short[locale] || resource?.short[DEFAULT_LOCALE] || "";
}
